import{_ as o,o as a,c as r,a3 as l}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"2.1 Hello World：蓝铁矿的命途分叉","description":"","frontmatter":{"translationSource":{"title":"2.1 Hello World：蓝铁矿的命途分叉","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=EtRfKcfCGHwRQxAFs7gkqI","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road"}]]},"headers":[],"relativePath":"zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road.md","filePath":"zh/page-EtRfKcfCGHwRQxAFs7gkqI.md"}'),s={name:"zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road.md"};function t(n,e,i,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[l('<div class="logistics-content"><span class="logistics-source-anchor" id="_2-1-hello-world-蓝铁矿的命途分叉" aria-hidden="true"></span><h1 id="_2-1-hello-world-蓝铁矿的命途分叉" tabindex="-1">2.1 Hello World：蓝铁矿的命途分叉 <a class="header-anchor" href="#_2-1-hello-world-蓝铁矿的命途分叉" aria-label="Permalink to &quot;2\\.1 Hello World：蓝铁矿的命途分叉&quot;">​</a></h1><blockquote><p>源页面 ID：<code>EtRfKcfCGHwRQxAFs7gkqI</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=EtRfKcfCGHwRQxAFs7gkqI" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>考虑如下智能生产方案：<strong>先生产</strong><span class="mark-blue"><strong>铁零件</strong></span><strong>到装满储存箱，然后再开始生产</strong><span class="mark-blue"><strong>蓝铁瓶</strong></span>。使用<u>优先输出器</u>，可以很简单地达成这一目标，如下图所示。<span class="mark-blue">铁零件</span>装满存储箱后，配件机逐渐堵塞，</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d4dc7795b1ef1870.q90-f9d858c02b714c06.webp" alt="21 Hello World：蓝铁矿的命途分叉"></p><p>麻雀虽小五脏俱全。虽然简单，但是这个例子已经包括了阻塞生产的绝大部分概念：</p><ol><li><p><strong>两种生产状态（两条生产通路）</strong>：生产<span class="mark-blue">铁零件</span>（30/m）以及生产<span class="mark-blue">蓝铁瓶</span>（15/m）</p></li><li><p><strong>阻塞信号</strong>：<span class="mark-blue">铁零件</span>首先装满储存箱，然后向上游传播，逐渐阻塞配件机</p></li><li><p><strong>生产状态如何发生变化</strong>：配件机及其直接上游传送带阻塞后，<span class="mark-blue">蓝铁块</span>自然地流向塑形机开始生产<span class="mark-blue">蓝铁瓶</span>。</p></li></ol><p>这些概念实质上构成了一个最为基本的阻塞生产单元。后面所述的各类阻塞生产结构，其可能在具体生产流程设计，设备布局等方面更加复杂，但核心逻辑是和这一基础单元一致的。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-efb1e399d855a670.q90-23363ebc0ea99fec.webp" alt="21 Hello World：蓝铁矿的命途分叉"></p><p><a href="/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking">2.2 花开两朵：切换型阻塞与平衡型阻塞</a></p></div>',1)])])}const g=o(s,[["render",t]]);export{f as __pageData,g as default};
